now=datetime.datetime.now(datetime.timezone.utc).isoformat(); read=lambda p:json.loads(pathlib.Path(p).read_text()); sha=lambda p:'sha256:'+hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest(); rows=lambda p:[json.loads(x) for x in pathlib.Path(p).read_text().splitlines() if x]; bind=lambda p:{'path':str(pathlib.Path(p).relative_to(R)) if pathlib.Path(p).is_relative_to(R) else str(p),'sha256':sha(p),'bytes':pathlib.Path(p).stat().st_size}
def write(p,x):
 p=pathlib.Path(p);p.parent.mkdir(parents=True,exist_ok=True);q=p.with_name(p.name+'.tmp');q.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n');os.replace(q,p)
def write_lines(p,x):
 p=pathlib.Path(p);p.parent.mkdir(parents=True,exist_ok=True);q=p.with_name(p.name+'.tmp');q.write_text(''.join(json.dumps(v,ensure_ascii=False)+'\n' for v in x));os.replace(q,p)
def diff(a,b,path=''):
 if type(a)!=type(b):return [{'path':path,'before':a,'after':b}]
 if isinstance(a,dict):return sum((diff(a.get(k),b.get(k),path+'/'+k) for k in sorted(a.keys()|b.keys())),[])
 if isinstance(a,list):
  if len(a)!=len(b):return [{'path':path,'before':a,'after':b}]
  return sum((diff(x,y,path+'/'+str(i)) for i,(x,y) in enumerate(zip(a,b))),[])
 return [] if a==b else [{'path':path,'before':a,'after':b}]
# Six independent understanding fields, scientific case audit and scope boundary per goal.
N={
'ce19': ['Dendriten/Zellkörper nehmen im gegebenen Grundmodell Signale auf; Axon und Endigungen unterscheiden Weiterleitung von Weitergabe.','In the supplied basic model, dendrites/cell body receive signals; axon and terminals distinguish conduction from transmission.','Die Person erklärt eine beschriftete Grundmodellroute zwischen zwei Zellen.','The learner explains a labelled basic-model route between two cells.','Ein weiterhin messbares Axonsignal beweist bei getrennten Endigungen keine Weitergabe zum Folgeneuron.','With disconnected terminals, a recorded axonal signal does not prove transmission to the next neuron.','Beide Fälle unterscheiden Struktur-Funktion, Weiterleitung und Übertragung korrekt. Die zweite Intervention ist fachlicher Transfer; keine universelle Aussage über alle Neuronentypen oder erneute vollständige AP-Ionenprüfung.','HE43 allgemeiner Bau/Funktion; BY13 EA/GA Kompetenz Aufbau skizzieren/Struktur-Funktion.'],
'ff1b': ['An der gegebenen erregenden ACh-Synapse koppelt spannungsabhängiger Ca-Einstrom ACh-Freisetzung an ligandengesteuerten postsynaptischen Strom.','At the supplied excitatory ACh synapse, voltage-gated calcium influx couples ACh release to ligand-gated postsynaptic current.','Ca-Einstrom, Vesikel, ACh, Rezeptorstrom und mögliche Schwellenüberschreitung werden kausal geordnet.','Calcium entry, vesicles, ACh, receptor current and possible threshold crossing are causally ordered.','Ein frischer unterschwelliger postsynaptischer Verlauf zeigt chemische Übertragung ohne zwingendes postsynaptisches AP.','A fresh subthreshold postsynaptic trace shows chemical transmission without a necessary postsynaptic action potential.','Nicotinischer ACh-Modellkontext ist explizit. Präsynaptische spannungsabhängige Ca-Kanäle, postsynaptische ligandabhängige Kationenkanäle und erst bei Schwelle VG-Na/AP sind getrennt; AChE baut ACh ab. Einzelvesikel garantiert kein AP. Keine elektrische Synapsenpflicht ergänzt.','HE43 erregende chemische ACh-Synapse/Kanäle; BY13 elektrochemische Übertragung. Ganze Stoff/NMJ-Quellenpflichten nicht daraus geschlossen.'],
'a46c': ['Bei gleichen Eingängen ändern gegebene wirksame Verbindungsgewichte die Verarbeitung eines ausdrücklich begrenzten Netzmodells.','With identical inputs, supplied effective connection weights change processing in an explicitly bounded network model.','Die Person berechnet Vorher-/Nachher-Potenziale und erklärt die geänderten Ausgänge.','The learner calculates before/after potentials and explains changed outputs.','Im neuen Modell unterscheidet eine stärkere hemmende Verbindung bei gleichen Eingängen einen Schwellenfall von einem unterschwelligen Fall.','In the fresh model, a stronger inhibitory connection distinguishes threshold and subthreshold outcomes at identical inputs.','u=-70+wA*xA+wB*xB, Schwelle-55: vorher -64/-60/-54, nachher -54/-60/-44; nur vorher(1,1), nachher(1,0)/(1,1) lösen aus. Frisch P=-55 löst aus, Q=-60 nicht. Persistente wirksame Gewichte sind gegeben; keine neue Kontaktbildung, Molekülursache, Gedächtnis oder Lernregel daraus erfunden.','HE43 zelluläre Lernprozesse/BY13EA Plastizität; deklarierte didaktische Spezialisierung, kein amtliches separates Netzänderungsbullet.'],
'7874': ['Rezeptorpotenziale sind abgestufte Antworten; primäre und sekundäre Sinneszellen unterscheiden sich im eigenen Axon beziehungsweise der Übertragung an ein separates Neuron.','Receptor potentials are graded responses; primary and secondary sensory cells differ in having their own axon versus transmitting to a separate neuron.','Zellmodelle A und B werden anhand der gegebenen Signalroute begründet zugeordnet.','Cell models A and B are classified with reasons based on the supplied signalling route.','Ein hyperpolarisierendes Rezeptorpotenzial mit veränderter Transmitterfreisetzung bleibt eine mögliche sensorische Antwort.','A hyperpolarising receptor potential with changed transmitter release remains a possible sensory response.','Primär/sekundär über tatsächliche Zelltopologie getrennt, Rezeptorpotenzial nicht AP; frischer Fall verhindert die falsche Universalregel jede Rezeptorantwort sei depolarisierend. Kein vollständiges optisches Modell vorausgesetzt.','HE43 LK Rezeptorpotenzial/primäre und sekundäre Sinneszellen; begriffliche Voraussetzung zu8b, keine verdeckte Gesamtzielvererbung.'],
'1975': ['Neuronales Signal, Hormonausschüttung und rezeptorabhängige Zielorganantwort bilden den gegebenen gemeinsamen Steuerungsweg.','Neural signal, hormone release and receptor-dependent target-organ responses form the supplied combined control pathway.','Die Person erklärt verschiedene Antworten zweier Zielorgane bei gleichem Hormonsignal.','The learner explains different responses of two target organs to the same hormone signal.','Ein selektiv blockierter Zielrezeptor kann eine Antwort verhindern, obwohl neuronaler Weg und Hormonmenge bestehen bleiben.','A selectively blocked target receptor can prevent one response while the neural pathway and hormone amount remain intact.','Beide Fälle tragen gemeinsame hormonelle/neuronale Steuerung und rezeptorspezifische Wirkung. Selektiver Rezeptorblock ist kein globaler Stressblock. Keine zusätzlich verlangte negative Rückkopplung aus c05.','HE43 LK gemeinsames Wirken hormoneller/neuronaler Systeme; keine pauschale ganze BY-Stresspflichtfreigabe.'],
'e111': ['Räumliche und zeitliche Überlagerung von EPSP/IPSP verändert die Annäherung an die AP-Schwelle.','Spatial and temporal overlap of EPSPs/IPSPs changes approach to action-potential threshold.','Eine ausdrücklich additive Momentaufnahme wird berechnet und im Schwellenmodell ausgewertet.','An explicitly additive snapshot is calculated and interpreted in the threshold model.','Abstände zwischen EPSP und ein frisches IPSP werden am gegebenen Verlauf statt aus Einzelamplituden allein beurteilt.','EPSP spacing and a fresh IPSP are evaluated from the supplied combined trace rather than individual amplitudes alone.','-70+8+10-5=-57 unterschwellig; ohne Hemmung -52 überschwelllig. Dies ist ein gegebener additiver Modellfall, keine echte Leitwertgleichung. Nahe EPSP überlagern eher; endgültiger Schwellenbefund verlangt den gemeinsamen Verlauf.','HE43 LK EPSP/IPSP, räumliche/zeitliche Summation, hemmende Synapse; gegenüber97 beschreibende Integration.'],
'3471': ['Persistente funktionelle Antwortänderung und strukturelle Kontaktänderung sind verschiedene zelluläre Plastizitätsbefunde.','Persistent functional response changes and structural contact changes are distinct cellular plasticity findings.','Bei konstantem Test ordnet die Person Antwort2→5 als funktionelle Änderung ein und benennt fehlende Struktur-/Ursachenbelege.','Under a fixed test, the learner interprets response2→5 as functional change and identifies missing structural/causal evidence.','Zusätzliche Kontaktstellen bei gleicher Einzelstärke werden als frischer struktureller Befund mit dem ersten Fall verglichen.','Additional contact sites with unchanged individual strength are compared as a fresh structural finding.','Beide vollständigen Fälle tragen allgemeines zelluläres Lernen. Verstärkte Antwort ohne Kontaktbild beweist keine neue Kontaktbildung oder molekulare Ursache; zusätzlicher Kontaktbefund ist strukturell. Kein Gedächtnis einer Person gemessen. DE/EN und inneres Profil exakt; ganzes347-Metadatenobjekt verändert.','HE43 zelluläre Prozesse des Lernens; BY13EA Plastizität. Nicht identisch mit Netzrechnen, Hebb-Regelanwendung oder LTP/LTD-Inferenz.'],
'485e': ['Eine gegebene neuronale Struktur- oder Signalstörung kann eine Systemfunktion beeinträchtigen, ohne dass ein einzelnes Symptom die Krankheit diagnostiziert.','A supplied neural structural or signalling disturbance can impair system function without a single symptom diagnosing a disease.','Die Person verbindet gegebenen Verbindungsverlust mit veränderter Verarbeitung und begrenzt die Diagnosefolgerung.','The learner links supplied connection loss to altered processing and limits diagnostic inference.','Strukturverlust und vorübergehende Transmitteränderung können ähnliche Beeinträchtigungen verursachen und werden getrennt.','Structural loss and temporary transmitter changes may cause similar impairments and are distinguished.','Alzheimer-Beispiel trägt die geforderte prinzipielle Erklärung. Ähnliche Symptome beweisen weder gleiche Ursache noch Zellverlust; Alzheimer, MS und Depression werden nicht gleichgesetzt.','HE43 LK eine neuronale Erkrankung prinzipiell; keine ganze BY-MS/Parkinson/Depressionspflicht ersetzt.'],
'afde': ['Das gegebene fMRT-BOLD-Signal bildet eine indirekte Verbindung zwischen Blutantwort und neuronaler Aktivität ab.','The supplied fMRI BOLD signal links blood response and neural activity indirectly.','Die Person erklärt Messgröße, Aufgaben-/Kontrollvergleich und die begrenzte Aktivitätsinterpretation.','The learner explains the measured quantity, task/control comparison and bounded activity interpretation.','Strukturelle MRT und funktioneller Vergleich beantworten im frischen Fall unterschiedliche Fragen.','Structural MRI and a functional comparison answer different questions in the fresh case.','BOLD ist keine direkte Messung jedes AP und kein Gedankenfoto. Anatomische MRT und bedingungsabhängiges Funktionssignal bleiben getrennt. Referenzfallmaterial ist konzeptionell, keine echte MRT-Durchführung behauptet.','HE43 LK ein bildgebendes Verfahren; nicht durch bloße EEG/ENG/EKG-Verfahrensliste ersetzt.'],
'2381': ['Potenzialmessungen benötigen definierte Mess-/Referenzelektrode, kontrollierten Reiz und einen zeitlich interpretierbaren Verlauf.','Potential recordings need defined recording/reference electrodes, a controlled stimulus and an interpretable time course.','Die Person plant vor/nach Reiz einen kontrollierten Modellvergleich und trennt Ruhe- von AP-Verlauf.','The learner plans a controlled before/after-stimulus model comparison and distinguishes resting and action-potential traces.','Ein frisch umgekehrt angeschlossener Referenzkanal wird als Vorzeichenänderung statt neue Zellfunktion erkannt.','A freshly reversed reference connection is identified as a sign change rather than a new cellular function.','Plan und Auswertung sind beide gefordert. -70 vor Reiz, rasch+30 danach, Rückkehr ist plausibler Modell-AP. Polungswechsel ändert Vorzeichen; Referenz und Kontrollen gehören zur Interpretation. Prose-Referenzmaterialspezifikation nicht als ausgeführtes Labor/Messgerätmaterial zertifiziert.','HE43 allgemeine Potenzialmessungen; Planungsoperator aus aktuellem Ziel bleibt erhalten.'],
'c9a0': ['Kontrollierte, länger anhaltende Änderung synaptischer Wirksamkeit trägt eine LTP-/LTD-Modellinterpretation innerhalb des beobachteten Zeitfensters.','Controlled sustained changes in synaptic efficacy support LTP/LTD model interpretations within the observed time window.','Die Person normalisiert Testantworten und prüft gleichbleibenden Test, Kontrolle und Dauer.','The learner normalises test responses and checks stable testing, control and duration.','Eine persistente Abschwächung, eine vorübergehende Änderung und eine Testreizverstärkung werden anhand frischer Kontrollen unterschieden.','Persistent weakening, transient change and stronger testing stimulation are distinguished using fresh controls.','T2→3.2/3.1/3.2 ergibt160/155/160% über5/30/60min; Kontrolle2/2/1.98/2. D4→2/2.1/2 unterstütztLTD, R4→2/3.7/4 transient, S4→6/6/6 bei stärkerem Test kein gleich-inputLTP-Beleg. Keine Statistik, Molekülursache, unbegrenzte Dauer oder Gedächtnis behauptet.','HE/BY allgemeine Plastizität; LTP/LTD sind deklarierte didaktische Modelle, keine eigenen amtlichen Pflichtbullets.'],
'4f63': ['Eine gegebene Hebb-Regel verändert Gewichte anhand vorgegebener gemeinsamer Aktivität; Modellgrenzen sind zusätzliche Annahmen.','A supplied Hebbian rule changes weights from given joint activity; model limits are additional assumptions.','Die Person wendet die tatsächlich vorgegebene Regel auf jede Runde an, ohne neuronale Aktivität aus Gewichten zu erfinden.','The learner applies the actually supplied rule in each round without inventing activity from weights.','Unbegrenztes Update und ausdrücklich begrenztes Update werden im frischen Grenzfall getrennt.','Unbounded and explicitly capped updates are distinguished in the fresh boundary case.','Start(.3,.2), Δ=.1*x*y: (.4,.2),(.4,.2),(.5,.3). Frisch A.8, eta.2, A1B0Y1 zweimal:U1.0/1.2, K1.0/1.0, B.2 bleibt. Kap1 ist gegebene Zusatzannahme, kein universelles biologisches Maximum; keine neue Variante erfunden.','HE/BY Plastizität als allgemeiner Kern; Hebb ausdrücklich didaktische Modellspezialisierung, nicht amtliche Einzelpflicht.'],
'97b2': ['Erregende und hemmende synaptische Einflüsse regulieren in gegebenen Verschaltungen das Erreichen von Schwellen.','Excitatory and inhibitory synaptic inputs regulate threshold crossing in supplied circuits.','Mehrere Verschaltungen werden anhand gegebener postsynaptischer Potenziale tatsächlich verglichen und E/I-Funktion abgeleitet.','Several circuits are actually compared using supplied postsynaptic potentials and the role of excitation/inhibition is inferred.','Eine selektive Hemmung eines divergenten Zweigs wird am frischen Zweizielmodell erklärt.','Selective inhibition of one divergent branch is explained in the fresh two-target model.','Konvergent-70+8=-62; +8+9=-53; +8+9-5=-58: nurE1+E2 löst aus. Divergent beide-54, H-6 nurZ2→Z2-60, Z1-54. Vergleich und Ableitungsoperator erfüllt, nicht bloße Topologie; keine Plastikgewichte/Hebb-Regel ergänzt.','BY13EA tatsächlicher Vergleich postsynaptischer Verschaltungen/Notwendigkeit E/I; e111 bleibt eigenständige Integration.'],
'9b96': ['Weniger Serotonin-Wiederaufnahme verändert Verfügbarkeit in einem gegebenen Synapsenmodell, aber erklärt Depression nur als begrenzte multifaktorielle Komponente.','Reduced serotonin reuptake changes availability in a supplied synaptic model, but explains only a bounded component of multifactorial depression.','Die Person unterscheidet Wiederaufnahmehemmung, Rezeptorblock und Freisetzung an der gegebenen Stoffbilanz.','The learner distinguishes reuptake inhibition, receptor block and release in the supplied balance model.','Ein frischer Transporterfall wird mit verschiedenen Stress-/Sozialkontexten ohne identische Therapie-/Symptomfolgerung eingeordnet.','A fresh transporter case is interpreted with differing stress/social contexts without inferring identical therapy or symptoms.','Einzelschritt10-8-1=1 versus10-3-1=6; keine zusätzliche Produktion/Akkumulationskurve/Rezeptorblock. Weniger Transporter kann Abklingen verzögern; keine alleinige Depressionsursache, sofortige Stimmung, Diagnose oder gleiche Therapie.','BY13EA/GA multifaktorielle Depression nur mechanistische Teilkomponente. Ganze Symptome/soziales Verständnis/Therapie offen.'],
'f628': ['Der gegebene Stoff verändert die ausdrücklich erregende ACh-Synapse an einer spezifizierten Stelle; NMJ-Wirkung folgt aus dem Übertragungsmechanismus.','The supplied substance changes the explicitly excitatory ACh synapse at a specified site; NMJ effects follow from the transmission mechanism.','Die Person leitet selektiven nicotinischen Rezeptorblock bei unveränderter Freisetzung/Ca/AChE bis zur Muskelantwort ab.','The learner traces selective nicotinic receptor block with unchanged release/calcium/AChE through to muscle response.','Partielle AChE-Hemmung wird als längere ACh-/Endplattenwirkung ohne pauschal größeres AP erklärt.','Partial AChE inhibition is explained as prolonged ACh/endplate effects without a universally larger action potential.','X verhindert gegebenes Rezeptoröffnen→keinen entsprechenden Kationenstrom/Depolarisation/über diesen NMJ-Weg ausgelöstes MuskelAP. Y partielleAChE-Hemmung kann Wirkung verlängern; APall-or-none nicht größer, Kontraktion nicht zwangsläufig stärker. ACh-Abbau nichtWiederaufnahme.','HE43 explizite ACh-, Stoff- und NMJ-Komponente in DE/EN erfüllt; keine beliebige allgemeine Neuropharmfreigabe.'],
'8b23': ['Ein gegebenes Sinneszellmodell koppelt Teilchenfluss, abgestuftes Rezeptorpotenzial und nachgeschaltetes AP-Muster zur Reizantwort.','A supplied sensory-cell model links particle flux, graded receptor potential and downstream action-potential pattern to stimulus response.','Die Person erklärt Kationeneinstrom bis Spikefrequenz und wendet dies auf Stärke/Dauer des gegebenen Falls an.','The learner explains cation influx through spike frequency and applies this to strength/duration in the supplied case.','Gleiche Stärke bei1s/4s und kompletter Kanalblock werden im ausdrücklich nichtadaptierenden Modell getrennt gedeutet.','Equal intensity at1s/4s and complete channel block are distinguished in the explicitly nonadapting model.','Mechanosensorischer primärer Modellfall:2s schwachRP2/f5 versusstarkRP6/f15, AP-Höhe gleich. Stärke überFrequenz, Dauer1vs4s überDauer des gleichfrequenten Musters. Kompletter Kanalblock:keine reizabhängigeRP/AP-Zunahme, spontaneGrundaktivität unbestimmt. Keine universelle Linearität/Adaptation/Rhodopsinmodelle ergänzt.','BY13EA Teilchen-Rezeptorpotential/Anwendung auf Sinnesphänomen;787 Zelltopologie und04d AP bleiben transparent gekoppelt, keine ganze Optikpflicht geschlossen.'],
'1b38': ['Das Flüssig-Mosaik-Modell verbindet bewegliche Bilayerbestandteile und selektive Membranwege mit Kompartimenttransport.','The fluid-mosaic model links mobile bilayer components and selective membrane pathways to compartment transport.','KanalA entlang gegebenem Gradienten und ATP-PumpeB entgegen gegebenem Gradienten werden getrennt erklärt.','ChannelA down the supplied gradient and ATP-pumpB against the supplied gradient are explained separately.','Ein selektiver Kanalverschluss lässt im frischen Modell unabhängige Pump- und neutrale Lipidwege bestehen.','Selective channel closure leaves independent pump and neutral lipid routes intact in the fresh model.','FMM, Selektivität, passiver Kanal und energiegekoppelte Pumpe fachlich korrekt. NurA geschlossen stoppt nichtB/C. GenericModellgradient gegeben; keine tatsächliche Ionennettoflussrichtung allein aus Konzentration oder universelle Permeabilität behauptet.','BY13EA/GA Kompetenz FMM beschreiben/Transport erläutern; kanonischeSekII-Prüfsicht keine ersteUnterrichtsstufenbehauptung.'],
'e3fb': ['Ionenverteilung und selektive Permeabilität ermöglichen eine dünne Membranladungstrennung; Energie erhält die zugrunde liegenden Gradienten.','Ion distribution and selective permeability enable thin membrane charge separation; energy maintains the underlying gradients.','Die Person erklärt gegebenes innennegatives Ruhepotenzial anhandK-Verteilung/Permeabilität und elektrischer Gegenkraft.','The learner explains the supplied negative resting potential fromK distribution/permeability and electrical counterforce.','Pumpstopp wird bei zunächst bestehenden, später abnehmenden Gradienten ohne sofortiges Nullpotenzial erklärt.','Pump stoppage is explained with initially persisting, later declining gradients without instantaneous zero potential.','Kinnenhoch/außenniedrig, K-Permeabilität und zurückgehaltene negative Impermeanten passen innennegativer Messung. Dünne Ladungstrennung kein gesamtes Zellvolumen negativ. PumpeGradientenwartung nichtalleinsofortigeLadungsursache;keineexakteNernstzahl verlangt.','BY13EA/GA tatsächliche Messdaten/Ladungsverhältnisse/Energieableitung; aktuellesZieloperator ganz erhalten.'],
'04d7': ['Spannungsabhängige Na-/K-Leitfähigkeiten erklären AP-Verlauf; bei gleich hohen Impulsen kann Frequenz Information tragen.','Voltage-gated sodium/potassium conductances explain the action-potential trace; equal-height pulses can encode information through frequency.','Die Person erklärt Na-Einstrom, spätereK-Leitfähigkeit und Schwellenereignis auf Teilchenebene.','The learner explains sodium influx, later potassium conductance and threshold event at particle level.','Ein stärkerer längerer Reiz wird mit mehr gleich hohen Impulsen und refraktär begrenzter Frequenz gedeutet.','A stronger longer stimulus is interpreted with more equal-height pulses and refractory-limited frequency.','GegebenerNa-Anstieg/spätereK-Leitfähigkeit trägt schnellen Verlauf; Pumpe keine schnelleRepolarisation. Unterschwellig keinvollerImpuls. StärkererReiz kann Frequenz stattAP-Höhe ändern, Refraktärzeit begrenzt Frequenz. Keine unbegrenzteCodierung/universelle Rezeptorregel.','BY13EA/GA Teilchen-AP undCodierung;8b ergänzt gegebenenRezeptor/Sinnesfall, ohne04dgesamtes neu zuüberladen.'],
'080b': ['Kontinuierliche und saltatorische Leitung sowie Durchmesser/Myelin begrenzen die Erklärung gegebener Leistungsunterschiede zwischen Wirbellosen und Wirbeltieren.','Continuous/saltatory conduction and diameter/myelin constrain explanations of supplied performance differences between invertebrates and vertebrates.','Die Person vergleicht gegebene Nervenfasern und erklärt konkret zugeordnete Tiergruppenleistung aus den gegebenen Merkmalen/Daten.','The learner compares supplied fibres and explains explicitly assigned animal-group performance from the supplied traits/data.','Ein neuer Mehrfaktorfall erlaubt ohne weitere Daten keine pauschale Tiergruppen-Geschwindigkeitsrangfolge.','A fresh multifactor case does not allow a universal animal-group speed ranking without further data.','P_REVISE: Modelllaufzeiten1/10=.1s,1/50=.02s korrekt und saltatorischeMechanik korrekt. Fall1 nennt keine Wirbellosen-/Wirbeltierzuordnung. Fall2 liefert nur die richtige Grenze gegen ein universellesRanking; keine positive konkret zugeordneteTiergruppen-Leistungsinferenz. Erwartung observablePerformance verlangt nurFaser-/Laufzeitdaten. Ganze aktuelleDE/EN-Pflicht damit nicht vollständig demonstrierbar.','BY13EA/GA tatsächliche Kompetenz vergleicht Fasern und erklärt daraus Leistung vonWirbellosen/Wirbeltieren. DKEEP; keine neueArtenkenntnis/zusätzlicheAufgabenquote verlangt.'],
'c05e': ['Negative Rückkopplung reguliert Hormonkonzentrationen; ein anhaltender Stresspfad kann in einem gegebenen Modell einen zweiten Regelkreis beeinflussen.','Negative feedback regulates hormone concentrations; persistent stress input can affect a second loop in a supplied model.','Die Person beschreibt gegebenen Cortisolkreis und begründet Abklingen nach endendem Trigger.','The learner describes the supplied cortisol loop and explains decline after the trigger ends.','Im frischen gekoppelten Cortisol-/Glucose-/Insulinmodell werden beendeter und anhaltender Stress mechanistisch verglichen.','Ended and persistent stress are compared mechanistically in the fresh coupled cortisol/glucose/insulin model.','CortisolnegativesUpstreamfeedback→nachTriggerendeAbklingen, nichtnegativeKonzentration. FrischStressCortisol↑→Glucoseantrieb; Glucose↑→Insulin↑→Aufnahme↑→Glucose↓→Insulin↓. AnhaltenderInput kann gekoppelteRegulationbeeinflussen;keineInsulinresistenz, klinischeDiagnose oderexakteLangzeitwirkung erfunden.','BY13EA tatsächlicheRegulationskompetenz/chronicStressandererHormonkreis;197gemeinsameSteuerung separat.']}
